        initialMousePos: { x: 0, y: 0 },
        imageWidth: 300,
        imageHeight: 400,
        savedImageUrl: null, // Store the data URL of the saved image
        change_images:false,
        show_spinner:false,
        show_spinner1:false,
        change_mail:'',
        headers: {
          smail: '*_~'
        },
        is_up:false,
        imgDataUrl: '',
        change_password:'',
        change_confirm_pass:'',
        jshshr:'',
        class_name:'',
        school_name:'',
