        langType: {
          hint: 'Rasm yuklash uchun bu joyni bosing yoki sudrab olib keling',
          loading: 'Yuklanmoqda...',
          noSupported: 'Sizning brauzeringiz rasm yuklashni qo‘llab-quvvatlamaydi, iltimos brauzeringizni yangilang!',
          success: 'Yuklash muvaffaqiyatli amalga oshirildi!',
          fail: 'Yuklashda xato yuz berdi.',
          preview: 'Oldindan ko‘rish',
